  const resetMinions=()=>{S.minions=[];for(let i=0;i<S.summonCount;i++){const a=i/S.summonCount*Math.PI*2;S.minions.push({x:S.x+Math.cos(a)*38,y:S.y+Math.sin(a)*38,cd:Math.random()*.4,hp:S.summonHealth,max:S.summonHealth})}};
  const originalHit=hit;hit=(enemy,damage)=>{const alive=enemy.hp>0;originalHit(enemy,damage);if(alive&&enemy.hp<=0&&S){S.abilityCharge=Math.min(2,(S.abilityCharge||0)+1);S.ultCharge=Math.min(10,(S.ultCharge||0)+1);if(Math.random()<.4){S.coins=(S.coins||0)+1;S.coinFlash=.8;burst(enemy.x,enemy.y,'#ffd45a',16);tone(760,.035)}}};
  const originalAttack=attack;attack=()=>{if(!S||S.paused)return;const ready=S.attackCd<=0;if(S.classId==='warden'){if(!ready)return;S.attackCd=1/S.rate;for(const enemy of S.enemies)if(enemy.hp>0&&Math.hypot(enemy.x-S.x,enemy.y-S.y)<88)hit(enemy,S.damage);S.wardenPulse=.22;S.attackAnim=.28;tone(145,.04);return}if(S.classId==='mystic'){if(!ready)return;S.attackCd=1/S.rate;const aim=Math.atan2(mouse.y-S.y,mouse.x-S.x);for(const spread of[-.24,0,.24]){const a=aim+spread;S.shots.push({x:S.x,y:S.y,vx:Math.cos(a)*560,vy:Math.sin(a)*560,r:S.size+1,life:.8,damage:S.damage})}S.attackAnim=.25;tone(440,.025);return}if(S.classId==='voidcaller'){if(S.beamTimer<=0&&S.beamCooldown<=0){S.beamTimer=3;S.beamAngle=Math.atan2(mouse.y-S.y,mouse.x-S.x);S.attackAnim=.35;tone(80,.06)}return}originalAttack();if(ready)S.attackAnim=.22};
  const castAbility=()=>{if(!S||S.paused||S.abilityCharge<2)return;if(S.classId==='blade'){S.shieldSavedHp=S.hp;S.maxHp+=100000;S.hp+=100000;S.shieldTimer=5;S.abilityCharge=0;tone(520,.05)}else if(S.classId==='necromancer'){S.speed*=1.7;S.speedTimer=5;S.abilityCharge=0;tone(620,.05)}else if(S.classId==='ranger'){for(const enemy of S.enemies)if(Math.hypot(enemy.x-S.x,enemy.y-S.y)<92)hit(enemy,S.damage*2);const aim=Math.atan2(mouse.y-S.y,mouse.x-S.x);for(const spread of[-.34,-.17,0,.17,.34]){const a=aim+spread;S.shots.push({x:S.x,y:S.y,vx:Math.cos(a)*600,vy:Math.sin(a)*600,r:5,life:1.1,damage:S.damage*1.35})}S.attackAnim=.35;S.abilityCharge=0}else if(S.classId==='mystic'){for(const enemy of S.enemies){enemy.speed*=.45;enemy.slowTimer=3}S.abilityCharge=0;tone(260,.05)}else if(S.classId==='warden'){const run=S,a=Math.atan2(mouse.y-S.y,mouse.x-S.x),started=performance.now();run.dashSavedHp=run.hp;run.maxHp+=100000;run.hp+=100000;run.dashTimer=1.5;run.abilityCharge=0;run.attackAnim=.35;tone(680,.06);const dash=setInterval(()=>{if(S!==run){clearInterval(dash);return}const elapsed=performance.now()-started;run.x=Math.max(35,Math.min(925,run.x+Math.cos(a)*8.5));run.y=Math.max(70,Math.min(605,run.y+Math.sin(a)*8.5));run.dashTimer=Math.max(0,1.5-elapsed/1000);burst(run.x,run.y,'#a6d482',2);if(elapsed>=1500){clearInterval(dash);run.maxHp-=100000;run.hp=Math.min(run.maxHp,Math.max(run.hp-100000,run.dashSavedHp));run.dashTimer=0}},16)}else if(S.classId==='voidcaller'){const run=S,turret={x:S.x,y:S.y,life:5,angle:0};run.turrets??=[];run.turrets.push(turret);run.abilityCharge=0;tone(360,.06);const started=performance.now(),fire=setInterval(()=>{if(S!==run||performance.now()-started>=5000){clearInterval(fire);if(S===run)run.turrets=run.turrets.filter(t=>t!==turret);return}turret.life=5-(performance.now()-started)/1000;const enemy=run.enemies.reduce((best,e)=>!best||Math.hypot(e.x-turret.x,e.y-turret.y)<Math.hypot(best.x-turret.x,best.y-turret.y)?e:best,null);if(!enemy)return;turret.angle=Math.atan2(enemy.y-turret.y,enemy.x-turret.x);run.shots.push({x:turret.x,y:turret.y,vx:Math.cos(turret.angle)*620,vy:Math.sin(turret.angle)*620,r:5,life:1.4,damage:run.damage*.65*(run.turretPower||1)});burst(turret.x+Math.cos(turret.angle)*16,turret.y+Math.sin(turret.angle)*16,'#c071e8',3)},280)}};
