  const originalInit=init;init=()=>{setBackground();originalInit();S.unlockedAbilities=new Set();S.enemyShots=[];S.abilityCharge=0;S.ultCharge=0;S.coins=0;S.coinFlash=0;S.shieldTimer=0;S.speedTimer=0;S.explosionTimer=0;S.attackAnim=0;S.wardenPulse=0;S.beamTimer=0;S.beamCooldown=0;S.beamAngle=0;S.mysticBeam=false;S.mysticBeamTimer=0;S.targetingRain=false;S.arrowRain=0;S.nextRest=3+Math.floor(Math.random()*4);while(S.nextRest%5===0||S.nextRest%5===4)S.nextRest++;S.summonCount=S.classId==='necromancer'?2:0;S.summonDamage=10;S.summonRate=1;S.summonHealth=55;resetMinions();ui()};
